        html += '<div style="width:32px;height:32px;background:#E4E8ED;border-radius:8px;display:flex;align-items:center;justify-content:center;">';
        html += '<svg width="16" height="16" viewBox="0 0 24 24" fill="#5A6B7D"><path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>';
