        html += '#chat-avatar:hover { transform:scale(1.1) rotate(5deg); }';
        html += '#chat-back-btn:hover { background:#E9ECEF; }';
        html += '.toolbar-btn:hover { background:#E4E8ED !important; }';
        html += '.toolbar-btn:active { transform:scale(0.96); }';
        html += '@keyframes messageIn { from { opacity:0;transform:translateY(15px); } to { opacity:1;transform:translateY(0); } }';
        html += '@keyframes poke { 0%,100% { transform:translateX(0) scale(1); } 25% { transform:translateX(-3px) rotate(-3deg) scale(1.1); } 75% { transform:translateX(3px) rotate(3deg) scale(1.1); } }';
