                    // 组头部 - 简洁设计
                    html += '<div class="fav-group-header" data-group-id="' + groupUniqueId + '" style="padding:14px 16px;display:flex;align-items:center;justify-content:space-between;cursor:pointer;user-select:none;transition:background 0.15s;">';
