    // ============ 分享到微博功能 ============
    
    // 打开分享到微博弹窗
    ChatApp.prototype.openShareToWeiboModal = function(aiId, msgId, msgRole) {
        var self = this;
        var ai = PhoneCore.getAI(aiId);
        if (!ai) return;
        
        // 找到消息内容
        var msg = null;
        if (ai.chatHistory) {
            for (var i = 0; i < ai.chatHistory.length; i++) {
                if (String(ai.chatHistory[i].id) === String(msgId)) {
                    msg = ai.chatHistory[i];
                    break;
                }
            }
        }
        
        if (!msg) {
            this.showToast('找不到该消息');
            return;
        }
        
        // 提取消息文本内容
        var msgContent = '';
        if (msg.content) {
            msgContent = msg.content;
        } else if (msg.voiceContent) {
            msgContent = msg.voiceContent;
        } else if (msg.redpacketCard) {
            msgContent = '[红包] ' + (msg.redpacketCard.message || '恭喜发财');
        } else if (msg.transferCard) {
            msgContent = '[转账] ¥' + msg.transferCard.amount.toFixed(2);
        } else if (msg.locationCard) {
            msgContent = '分享位置：' + (msg.locationCard.name || '某地点');
        } else {
            this.showToast('此消息类型不支持分享');
            return;
        }
        
        // 获取用户名
        var userName = '用户';
        var mask = PhoneCore.user && PhoneCore.user.getCurrentMask ? PhoneCore.user.getCurrentMask() : null;
        if (mask && mask.name) {
            userName = mask.name;
        } else if (PhoneCore.user && PhoneCore.user.name) {
            userName = PhoneCore.user.name;
        }
        
        // 构建默认微博内容
        var defaultContent = '';
        if (msgRole === 'assistant') {
            defaultContent = '和' + ai.name + '聊天时ta说：「' + msgContent.substring(0, 100) + (msgContent.length > 100 ? '...' : '') + '」';
        } else {
            defaultContent = msgContent.substring(0, 200) + (msgContent.length > 200 ? '...' : '');
        }
        
        // 创建弹窗
        var modal = document.createElement('div');
        modal.className = 'share-weibo-modal';
        modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1000;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.2s ease;';
        
        var modalContent = '<div style="width:90%;max-width:400px;background:#fff;border-radius:16px;box-shadow:0 10px 40px rgba(0,0,0,0.2);overflow:hidden;animation:slideUp 0.3s ease;">';
        
        // 标题栏
        modalContent += '<div style="padding:16px 20px;border-bottom:1px solid #f0f0f0;display:flex;align-items:center;justify-content:space-between;">';
        modalContent += '<span style="font-size:16px;font-weight:600;color:#333;">分享到微博</span>';
        modalContent += '<button class="close-share-weibo-modal" style="width:28px;height:28px;border:none;background:transparent;cursor:pointer;display:flex;align-items:center;justify-content:center;border-radius:50%;transition:background 0.2s;" onmouseover="this.style.background=\'#f5f5f5\'" onmouseout="this.style.background=\'transparent\'">';
        modalContent += '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#999" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg>';
        modalContent += '</button>';
        modalContent += '</div>';
        
        // 内容编辑区
        modalContent += '<div style="padding:16px 20px;">';
        modalContent += '<textarea id="share-weibo-content" placeholder="说点什么..." style="width:100%;height:120px;border:1px solid #e0e6ed;border-radius:10px;padding:12px;font-size:14px;line-height:1.6;resize:none;outline:none;font-family:inherit;transition:border-color 0.2s;" onfocus="this.style.borderColor=\'#6bb9f0\'" onblur="this.style.borderColor=\'#e0e6ed\'">' + this.escapeHtml(defaultContent) + '</textarea>';
        modalContent += '</div>';
        
        // @AI选项（只有分享AI消息时显示）
        if (msgRole === 'assistant') {
            modalContent += '<div style="padding:0 20px 16px;">';
            modalContent += '<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:14px;color:#666;">';
            modalContent += '<input type="checkbox" id="share-weibo-mention-ai" checked style="width:18px;height:18px;accent-color:#6bb9f0;">';
            modalContent += '<span>@' + ai.name + '</span>';
            modalContent += '</label>';
            modalContent += '</div>';
        }
        
        // 话题标签快捷添加
        modalContent += '<div style="padding:0 20px 16px;">';
        modalContent += '<div style="font-size:12px;color:#999;margin-bottom:8px;">添加话题</div>';
        modalContent += '<div style="display:flex;flex-wrap:wrap;gap:8px;">';
        var defaultTags = ['日常', '聊天记录', '有趣的对话'];
        defaultTags.forEach(function(tag) {
            modalContent += '<span class="share-weibo-tag" data-tag="' + tag + '" style="padding:6px 12px;background:rgba(248,165,194,0.15);color:#f8a5c2;border-radius:20px;font-size:13px;cursor:pointer;transition:all 0.2s;">#' + tag + '#</span>';
        });
        modalContent += '</div>';
        modalContent += '</div>';
        
        // 底部按钮
        modalContent += '<div style="padding:16px 20px;border-top:1px solid #f0f0f0;display:flex;gap:12px;">';
        modalContent += '<button class="cancel-share-weibo" style="flex:1;padding:12px;background:#f5f5f5;color:#666;border:none;border-radius:10px;font-size:14px;cursor:pointer;transition:background 0.2s;" onmouseover="this.style.background=\'#eee\'" onmouseout="this.style.background=\'#f5f5f5\'">取消</button>';
        modalContent += '<button class="confirm-share-weibo" style="flex:1;padding:12px;background:linear-gradient(135deg,#6bb9f0,#5aa8e0);color:white;border:none;border-radius:10px;font-size:14px;font-weight:500;cursor:pointer;box-shadow:0 2px 8px rgba(107,185,240,0.4);transition:all 0.2s;" onmouseover="this.style.transform=\'translateY(-1px)\';this.style.boxShadow=\'0 4px 12px rgba(107,185,240,0.5)\'" onmouseout="this.style.transform=\'translateY(0)\';this.style.boxShadow=\'0 2px 8px rgba(107,185,240,0.4)\'">发布微博</button>';
        modalContent += '</div>';
        
        modalContent += '</div>';
        modal.innerHTML = modalContent;
        document.body.appendChild(modal);
        
        var selectedTags = [];
        
        // 话题标签点击
        modal.querySelectorAll('.share-weibo-tag').forEach(function(tagEl) {
            tagEl.onclick = function() {
                var tag = tagEl.getAttribute('data-tag');
                var isSelected = tagEl.style.background.includes('107,185,240');
                
                if (isSelected) {
                    // 取消选中
                    tagEl.style.background = 'rgba(248,165,194,0.15)';
                    tagEl.style.color = '#f8a5c2';
                    selectedTags = selectedTags.filter(function(t) { return t !== tag; });
                } else {
                    // 选中
                    tagEl.style.background = 'rgba(107,185,240,0.2)';
                    tagEl.style.color = '#6bb9f0';
                    selectedTags.push(tag);
                }
            };
        });
        
        // 关闭按钮
        modal.querySelector('.close-share-weibo-modal').onclick = function() {
            modal.remove();
        };
        
        // 取消按钮
        modal.querySelector('.cancel-share-weibo').onclick = function() {
            modal.remove();
        };
        
        // 点击背景关闭
        modal.onclick = function(e) {
            if (e.target === modal) {
                modal.remove();
            }
        };
        
        // 发布按钮
        modal.querySelector('.confirm-share-weibo').onclick = function() {
            var content = modal.querySelector('#share-weibo-content').value.trim();
            if (!content) {
                self.showToast('请输入内容');
                return;
            }
            
            // 检查是否@AI
            var mentionAi = false;
            var mentionCheckbox = modal.querySelector('#share-weibo-mention-ai');
            if (mentionCheckbox && mentionCheckbox.checked) {
                mentionAi = true;
            }
            
            // 调用微博发布功能
            self.publishToWeibo(content, selectedTags, mentionAi ? ai.name : null, aiId);
            
            modal.remove();
        };
    };
    
    // 发布微博
    ChatApp.prototype.publishToWeibo = function(content, tags, mentionName, fromAiId) {
        var self = this;
        
        // 获取微博App实例
        var weiboApp = PhoneCore.apps && PhoneCore.apps['weibo-app'];
        if (!weiboApp) {
            this.showToast('微博应用未安装');
            return;
        }
        
        // 构建带@提及的内容
        var finalContent = content;
        var mentions = [];
        if (mentionName) {
            mentions.push(mentionName);
        }
        
        // 调用微博的createPost方法
        var newPost = weiboApp.createPost(finalContent, [], tags, mentions);
        
        if (newPost) {
            // 记录分享来源（用于避免循环）
            newPost.sharedFromChat = true;
            newPost.sharedFromAiId = fromAiId;
            
            this.showToast('已发布到微博');
            
            // 发送通知
            if (PhoneCore.notifications) {
                PhoneCore.notifications.send({
                    type: 'success',
                    title: '分享成功',
                    message: '聊天内容已发布到微博',
                    icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="#6bb9f0"><circle cx="12" cy="12" r="10"/><path d="M9 12l2 2 4-4" stroke="white" stroke-width="2" fill="none"/></svg>',
                    size: 'mini',
                    duration: 2000
                });
            }
        } else {
            this.showToast('发布失败，请稍后重试');
        }
    };
    
    // HTML转义辅助方法（如果不存在）
    ChatApp.prototype.escapeHtml = function(text) {
        if (!text) return '';
        return String(text)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    };
    
    // 重roll消息 - 重新生成AI回复
    ChatApp.prototype.rerollMessage = function(aiId, msgId, page) {
        var self = this;
        var ai = PhoneCore.getAI(aiId);
        if (!ai || !ai.chatHistory) return;
        
        // 使用过滤后的聊天历史查找消息，与renderMessages保持一致
        var filteredResult = this.getFilteredChatHistory(aiId);
        var filteredHistory = filteredResult.messages;
        
        var msg = null;
        var msgIndex = -1;
        
        // 首先尝试通过消息ID查找
        for (var i = 0; i < ai.chatHistory.length; i++) {
            var m = ai.chatHistory[i];
            if (m.id && String(m.id) === String(msgId)) {
                msg = m;
                msgIndex = i;
                break;
            }
        }
        // 如果没有找到，尝试通过过滤后数组的索引查找
        if (!msg) {
            var idx = parseInt(msgId);
            if (!isNaN(idx) && idx >= 0 && idx < filteredHistory.length) {
                msg = filteredHistory[idx];
                msgIndex = ai.chatHistory.indexOf(msg);
            }
        }
        
        if (msgIndex === -1) {
            this.showToast('找不到该消息');
            return;
        }
        
        // 确保是AI的消息
        if (msg.role !== 'assistant') {
            this.showToast('只能重roll AI的消息');
            return;
        }
        
        // 删除这条消息及其之后的所有消息
        ai.chatHistory = ai.chatHistory.slice(0, msgIndex);
        PhoneCore.saveAI(ai);
        
        // 刷新消息显示
        var messagesContainer = page.querySelector('#messages-container');
        if (messagesContainer) {
            messagesContainer.innerHTML = this.renderMessages(aiId);
            messagesContainer.scrollTop = messagesContainer.scrollHeight;
            this.bindMessageActions(page, aiId);
        }
        
        this.showToast('正在重新生成...');
        
        // 重新生成AI回复
        this.generateAIResponse(aiId, page);
    };
    
    // 编辑消息内容
    ChatApp.prototype.editMessage = function(aiId, msgId, page) {
        var self = this;
        var ai = PhoneCore.getAI(aiId);
        if (!ai || !ai.chatHistory) return;
        
        // 使用过滤后的聊天历史查找消息，与renderMessages保持一致
        var filteredResult = this.getFilteredChatHistory(aiId);
        var filteredHistory = filteredResult.messages;
        
        var msg = null;
        // 首先尝试通过消息ID查找
        for (var i = 0; i < ai.chatHistory.length; i++) {
            var m = ai.chatHistory[i];
            if (m.id && String(m.id) === String(msgId)) {
                msg = m;
                break;
            }
        }
        // 如果没有找到，尝试通过过滤后数组的索引查找
        if (!msg) {
            var idx = parseInt(msgId);
            if (!isNaN(idx) && idx >= 0 && idx < filteredHistory.length) {
                msg = filteredHistory[idx];
            }
        }
        
        if (!msg) {
            this.showToast('找不到该消息');
            return;
        }
        
        // 只能编辑文本消息
        if (msg.type === 'image' || msg.type === 'sticker' || msg.type === 'voice' || 
            msg.redpacketCard || msg.transferCard || msg.locationCard || msg.songCard || 
            msg.inviteCard || msg.chatRecord || msg.type === 'poke' || msg.type === 'call') {
            this.showToast('此类型消息不支持编辑');
            return;
        }
        
        var currentContent = msg.content || '';
        
        // 调用通用编辑弹窗
        this.openEditMessageModal(currentContent, function(newContent) {
            // 更新消息内容
            msg.content = newContent;
            msg.edited = true;
            msg.editedAt = Date.now();
            PhoneCore.saveAI(ai);
            
            // 刷新消息显示
            var messagesContainer = page.querySelector('#messages-container');
            if (messagesContainer) {
                messagesContainer.innerHTML = self.renderMessages(aiId);
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
                self.bindMessageActions(page, aiId);
            }
            
            self.showToast('消息已编辑');
        });
    };
    
    // 通用编辑消息弹窗 - 显示在手机壳内，灵动岛之下
    ChatApp.prototype.openEditMessageModal = function(currentContent, onConfirm) {
        var self = this;
        
        // 获取手机壳容器
        var container = this.appWindow || document.getElementById('phone-screen');
        if (!container) {
            this.showToast('无法打开编辑窗口');
            return;
        }
        
        // 移除已存在的编辑弹窗
        var existingModal = container.querySelector('.edit-msg-modal-overlay');
        if (existingModal) {
            existingModal.remove();
        }
        
        // 创建弹窗遮罩层（相对于手机壳定位）
        var modal = document.createElement('div');
        modal.className = 'edit-msg-modal-overlay';
        modal.style.cssText = 'position:absolute;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.4);z-index:999;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.2s ease;';
        
        // 弹窗内容 - 小巧精致
        var modalContent = document.createElement('div');
        modalContent.className = 'edit-msg-modal-content';
        modalContent.style.cssText = 'background:white;border-radius:12px;width:80%;max-width:240px;overflow:hidden;animation:slideUp 0.3s cubic-bezier(0.68,-0.55,0.265,1.55);box-shadow:0 4px 16px rgba(0,0,0,0.12);';
        
        // 头部 - 更紧凑
        var header = document.createElement('div');
        header.style.cssText = 'padding:12px 14px 8px;';
        header.innerHTML = '<div style="font-size:13px;font-weight:600;color:#333;text-align:center;">编辑消息</div>';
        
        // 内容区
        var body = document.createElement('div');
        body.style.cssText = 'padding:0 12px 12px;';
        
        var textarea = document.createElement('textarea');
        textarea.className = 'edit-msg-textarea';
        textarea.value = currentContent;
        textarea.placeholder = '输入内容...';
        textarea.style.cssText = 'width:100%;height:60px;border:1px solid #E5E5E5;border-radius:8px;padding:8px 10px;font-size:13px;color:#333;resize:none;outline:none;box-sizing:border-box;transition:border-color 0.2s;line-height:1.4;font-family:inherit;';
        
        body.appendChild(textarea);
        
        // 底部按钮区 - 更紧凑
        var footer = document.createElement('div');
        footer.style.cssText = 'display:flex;gap:8px;padding:0 12px 12px;';
        
        var cancelBtn = document.createElement('button');
        cancelBtn.textContent = '取消';
        cancelBtn.style.cssText = 'flex:1;padding:8px;border:none;background:#F5F5F5;border-radius:8px;font-size:13px;color:#666;cursor:pointer;';
        
        var confirmBtn = document.createElement('button');
        confirmBtn.textContent = '确定';
        confirmBtn.style.cssText = 'flex:1;padding:8px;border:none;background:#4A6FA5;border-radius:8px;font-size:13px;color:white;font-weight:500;cursor:pointer;';
        
        footer.appendChild(cancelBtn);
        footer.appendChild(confirmBtn);
        
        modalContent.appendChild(header);
        modalContent.appendChild(body);
        modalContent.appendChild(footer);
        modal.appendChild(modalContent);
        
        // 添加到手机壳容器
        container.appendChild(modal);
        
        // 聚焦到文本框并移动光标到末尾
        setTimeout(function() {
            textarea.focus();
            textarea.setSelectionRange(textarea.value.length, textarea.value.length);
        }, 100);
        
        // 文本框交互效果
        textarea.onfocus = function() {
            textarea.style.borderColor = '#A8C8EC';
        };
        textarea.onblur = function() {
            textarea.style.borderColor = '#E5E5E5';
        };
        
        // 按钮悬停效果
        cancelBtn.onmouseenter = function() {
            cancelBtn.style.background = '#EBEBEB';
        };
        cancelBtn.onmouseleave = function() {
            cancelBtn.style.background = '#F5F5F5';
        };
        confirmBtn.onmouseenter = function() {
            confirmBtn.style.background = '#3D5C8A';
        };
        confirmBtn.onmouseleave = function() {
            confirmBtn.style.background = '#4A6FA5';
        };
        
        // 关闭弹窗函数
        var closeModal = function() {
            modal.style.animation = 'fadeOut 0.2s ease forwards';
            setTimeout(function() {
                modal.remove();
            }, 200);
        };
        
        // 取消按钮
        cancelBtn.onclick = closeModal;
        
        // 点击遮罩层关闭
        modal.onclick = function(e) {
            if (e.target === modal) {
                closeModal();
            }
        };
        
        // 确认按钮
        confirmBtn.onclick = function() {
            var newContent = textarea.value.trim();
            if (!newContent) {
                self.showToast('消息内容不能为空');
                textarea.style.borderColor = '#F4A6CD';
                setTimeout(function() {
                    textarea.style.borderColor = '#E5E5E5';
                }, 600);
                return;
            }
            
            if (newContent === currentContent) {
                closeModal();
                return;
            }
            
            // 调用回调
            if (onConfirm) {
                onConfirm(newContent);
            }
            
            closeModal();
        };
        
        // 动画样式使用软件已有的fadeIn/fadeOut/slideUp
    };
    
    // 翻译消息
    ChatApp.prototype.translateMessage = function(aiId, msgId, page) {
        var self = this;
        var ai = PhoneCore.getAI(aiId);
        if (!ai || !ai.chatHistory) return;
        
        // 使用过滤后的聊天历史查找消息，与renderMessages保持一致
        var filteredResult = this.getFilteredChatHistory(aiId);
        var filteredHistory = filteredResult.messages;
        
        var msg = null;
        // 首先尝试通过消息ID查找
        for (var i = 0; i < ai.chatHistory.length; i++) {
            var m = ai.chatHistory[i];
            if (m.id && String(m.id) === String(msgId)) {
                msg = m;
                break;
            }
        }
        // 如果没有找到，尝试通过过滤后数组的索引查找
        if (!msg) {
            var idx = parseInt(msgId);
            if (!isNaN(idx) && idx >= 0 && idx < filteredHistory.length) {
                msg = filteredHistory[idx];
            }
        }
        
        if (!msg || !msg.content) {
            this.showToast('无法翻译此消息');
            return;
        }
        
        // 检查是否已经翻译过
        if (msg.translation) {
            // 切换显示/隐藏翻译
            msg.showTranslation = !msg.showTranslation;
            PhoneCore.saveAI(ai);
            var messagesContainer = page.querySelector('#messages-container');
            if (messagesContainer) {
                messagesContainer.innerHTML = this.renderMessages(aiId);
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
                this.bindMessageActions(page, aiId);
            }
            return;
        }
        
        // 显示翻译中状态
        this.showToast('正在翻译...');
        
        // 模拟翻译（实际项目中可接入翻译API）
        setTimeout(function() {
            // 简单的模拟翻译 - 检测语言并提供模拟翻译
            var translatedText = self.simulateTranslation(msg.content);
            
            msg.translation = translatedText;
            msg.showTranslation = true;
            PhoneCore.saveAI(ai);
            
            var messagesContainer = page.querySelector('#messages-container');
            if (messagesContainer) {
                messagesContainer.innerHTML = self.renderMessages(aiId);
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
                self.bindMessageActions(page, aiId);
            }
            
            self.showToast('翻译完成');
        }, 500);
    };
    
    // 模拟翻译功能
    ChatApp.prototype.simulateTranslation = function(text) {
        // 检测是否包含中文
        var hasChinese = /[\u4e00-\u9fa5]/.test(text);
        
        if (hasChinese) {
            // 中文转英文的模拟翻译
            var translations = {
                '你好': 'Hello',
                '早上好': 'Good morning',
                '晚上好': 'Good evening',
                '谢谢': 'Thank you',
                '不客气': "You're welcome",
                '再见': 'Goodbye',
                '是的': 'Yes',
                '不是': 'No',
                '我爱你': 'I love you',
                '今天': 'today',
                '明天': 'tomorrow',
                '昨天': 'yesterday'
            };
            
            var result = text;
            for (var cn in translations) {
                result = result.replace(new RegExp(cn, 'g'), translations[cn]);
            }
            
            // 如果没有匹配到，返回一个通用的翻译提示
            if (result === text) {
                return '[Translation] ' + text;
            }
            return result;
        } else {
            // 英文转中文的模拟翻译
            var translations = {
                'hello': '你好',
                'good morning': '早上好',
                'good evening': '晚上好',
                'thank you': '谢谢',
                'thanks': '谢谢',
                'goodbye': '再见',
                'bye': '再见',
                'yes': '是的',
                'no': '不是',
                'i love you': '我爱你',
                'today': '今天',
                'tomorrow': '明天',
                'yesterday': '昨天'
            };
            
            var lowerText = text.toLowerCase();
            var result = lowerText;
            for (var en in translations) {
                result = result.replace(new RegExp(en, 'gi'), translations[en]);
            }
            
            if (result === lowerText) {
                return '[翻译] ' + text;
            }
            return result;
        }
    };
    
    // 撤回消息
    ChatApp.prototype.recallMessage = function(aiId, msgId, page) {
        var ai = PhoneCore.getAI(aiId);
        if (!ai || !ai.chatHistory) return;
        
        // 使用过滤后的聊天历史查找消息，与renderMessages保持一致
        var filteredResult = this.getFilteredChatHistory(aiId);
        var filteredHistory = filteredResult.messages;
        
        var msg = null;
        var msgIndex = -1;
        
        // 首先尝试通过消息ID查找
        for (var i = 0; i < ai.chatHistory.length; i++) {
            var m = ai.chatHistory[i];
            if (m.id && String(m.id) === String(msgId)) {
                msg = m;
                msgIndex = i;
                break;
            }
        }
        // 如果没有找到，尝试通过过滤后数组的索引查找
        if (!msg) {
            var idx = parseInt(msgId);
            if (!isNaN(idx) && idx >= 0 && idx < filteredHistory.length) {
                msg = filteredHistory[idx];
                msgIndex = ai.chatHistory.indexOf(msg);
            }
        }
        
        if (msgIndex !== -1) {
            ai.chatHistory[msgIndex].content = '你撤回了一条消息';
            ai.chatHistory[msgIndex].type = 'recalled';
            ai.chatHistory[msgIndex].role = 'system'; // 设为系统消息，居中显示
            PhoneCore.saveAI(ai);
            
            var messagesContainer = page.querySelector('#messages-container');
            if (messagesContainer) {
                messagesContainer.innerHTML = this.renderMessages(aiId);
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
                this.bindMessageActions(page, aiId);
            }
            
            this.showToast('消息已撤回');
        }
    };
    
    // 添加到收藏
    ChatApp.prototype.addToFavorites = function(aiId, msgId, page) {
        var self = this;
        var ai = PhoneCore.getAI(aiId);
        if (!ai || !ai.chatHistory) return;
        
        // 使用过滤后的聊天历史查找消息，与renderMessages保持一致
        var filteredResult = this.getFilteredChatHistory(aiId);
        var filteredHistory = filteredResult.messages;
        
        var msg = null;
        // 首先尝试通过消息ID查找
        for (var i = 0; i < ai.chatHistory.length; i++) {
            var m = ai.chatHistory[i];
            if (m.id && String(m.id) === String(msgId)) {
                msg = m;
                break;
            }
        }
        // 如果没有找到，尝试通过过滤后数组的索引查找
        if (!msg) {
            var idx = parseInt(msgId);
            if (!isNaN(idx) && idx >= 0 && idx < filteredHistory.length) {
                msg = filteredHistory[idx];
            }
        }
        
        if (msg) {
            if (!ai.favorites) ai.favorites = [];
            
            // 检查是否已收藏
            var alreadyFavorited = ai.favorites.some(function(f) {
                return f.id === msg.id;
            });
            
            // 找到对应的收藏按钮
            var favoriteBtn = page.querySelector('.msg-favorite-btn[data-msg-id="' + msgId + '"]');
            var icon = favoriteBtn ? favoriteBtn.querySelector('svg') : null;
            
            if (alreadyFavorited) {
                // 取消收藏 - 添加动画效果
                // 【爱心动画】先放大再缩小淡出
                if (favoriteBtn) {
                    favoriteBtn.style.transform = 'scale(1.2)';
                }
                if (icon) {
                    icon.setAttribute('fill', '#FFB6C1');
                }
                
                setTimeout(function() {
                    if (favoriteBtn) {
                        favoriteBtn.style.transform = 'scale(0.8)';
                        favoriteBtn.style.opacity = '0.5';
                    }
                    
                    setTimeout(function() {
                        ai.favorites = ai.favorites.filter(function(f) {
                            return f.id !== msg.id;
                        });
                        PhoneCore.saveAI(ai);
                        
                        // 恢复按钮样式
                        if (icon) {
                            icon.setAttribute('fill', 'none');
                            icon.setAttribute('stroke', '#FF6B9D');
                        }
                        if (favoriteBtn) {
                            favoriteBtn.style.background = '#FFF';
                            favoriteBtn.style.transform = 'scale(1)';
                            favoriteBtn.style.opacity = '1';
                        }
                        
                        self.showToast('已取消收藏');
                    }, 150);
                }, 150);
                
                return;
            }
            
            ai.favorites.push({
                id: msg.id,
                content: msg.content,
                type: msg.type,
                role: msg.role,
                timestamp: msg.timestamp,
                favoritedAt: Date.now()
            });
            
            PhoneCore.saveAI(ai);
            
            // 更新按钮样式 - 变成实心淡粉色爱心，背景保持白色
            if (icon) {
                icon.setAttribute('fill', '#FFB6C1');
                icon.setAttribute('stroke', '#FFB6C1');
            }
            if (favoriteBtn) {
                favoriteBtn.style.animation = 'heartPulse 0.4s cubic-bezier(0.34,1.56,0.64,1)';
                setTimeout(function() { favoriteBtn.style.animation = ''; }, 400);
            }
            
            this.showToast('已收藏');
        }
    };
    
