        if (!msg) return;
        
        // 获取所有联系人
        var allAIs = Object.values(PhoneCore.ais).filter(function(a) { return a.id !== aiId; });
        
        var html = '<div class="forward-modal" style="position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1000;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.2s ease;">';
        html += '<div style="background:white;border-radius:16px;width:85%;max-width:320px;max-height:70%;overflow:hidden;display:flex;flex-direction:column;animation:slideUp 0.3s ease;">';
        
        // 标题
        html += '<div style="padding:16px;border-bottom:1px solid #f0f0f0;display:flex;justify-content:space-between;align-items:center;">';
        html += '<span style="font-weight:600;font-size:16px;color:#333;">转发到</span>';
        html += '<button id="close-forward-modal" style="border:none;background:none;font-size:20px;color:#999;cursor:pointer;">&times;</button>';
