    // 群设置
    ChatApp.prototype.openGroupSettings = function(groupId) {
        var self = this;
        var group = this.getGroupChat(groupId);
        if (!group) return;
        
        var html = '<div style="padding:20px;">';
        
        // 群头像和名称
        html += '<div style="text-align:center;margin-bottom:25px;">';
        html += '<div style="width:70px;height:70px;margin:0 auto 12px;border-radius:16px;background:#fff;display:grid;grid-template-columns:repeat(2,1fr);gap:2px;overflow:hidden;border:2px solid #D6E4FF;">';
        group.members.slice(0, 4).forEach(function(memberId) {
            var ai = PhoneCore.getAI(memberId);
            if (ai) {
                if (ai.avatar) {
                    html += '<div style="background:url(' + ai.avatar + ') center/cover;"></div>';
                } else {
                    html += '<div style="background:' + self.getAvatarColor(ai.id) + ';display:flex;align-items:center;justify-content:center;font-size:12px;color:white;">' + ai.name.charAt(0) + '</div>';
                }
            }
        });
        html += '</div>';
        html += '<div style="font-size:18px;font-weight:600;color:#333;">' + group.name + '</div>';
        html += '<div style="font-size:13px;color:#666;margin-top:4px;">' + group.members.length + '人</div>';
        html += '</div>';
        
        // 设置项
        html += '<div style="background:white;border-radius:16px;overflow:hidden;">';
        
        // 群名称
        html += '<div class="setting-item" id="edit-group-name" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<span style="flex:1;">群聊名称</span>';
        html += '<span style="color:#999;margin-right:8px;">' + group.name + '</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 群公告
        html += '<div class="setting-item" id="group-announcement-setting" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<span style="flex:1;">群公告</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 群成员
        html += '<div class="setting-item" id="group-members-setting" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<span style="flex:1;">群成员</span>';
        html += '<span style="color:#999;margin-right:8px;">' + group.members.length + '人</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 我的群昵称
        var myNickname = group.userNickname || PhoneCore.user.name || '我';
        html += '<div class="setting-item" id="my-group-nickname" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<span style="flex:1;">我的群昵称</span>';
        html += '<span style="color:#999;margin-right:8px;">' + myNickname + '</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 群管理员设置
        var adminCount = (group.admins || []).length;
        html += '<div class="setting-item" id="group-admins-setting" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<div style="width:32px;height:32px;background:linear-gradient(135deg,#FFD700,#FFA500);border-radius:8px;display:flex;align-items:center;justify-content:center;margin-right:12px;">';
        html += '<svg width="16" height="16" viewBox="0 0 24 24" fill="white"><path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 10.99h7c-.53 4.12-3.28 7.79-7 8.94V12H5V6.3l7-3.11v8.8z"/></svg>';
        html += '</div>';
        html += '<span style="flex:1;">群管理员</span>';
        html += '<span style="color:#FFA500;font-size:12px;margin-right:8px;">' + adminCount + '人</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 禁言管理
        var mutedCount = Object.keys(group.mutedMembers || {}).length;
        html += '<div class="setting-item" id="group-mute-setting" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<div style="width:32px;height:32px;background:linear-gradient(135deg,#FF6B6B,#EE5A5A);border-radius:8px;display:flex;align-items:center;justify-content:center;margin-right:12px;">';
        html += '<svg width="16" height="16" viewBox="0 0 24 24" fill="white"><path d="M16.5 12c0-1.77-1.02-3.29-2.5-4.03v2.21l2.45 2.45c.03-.2.05-.41.05-.63zm2.5 0c0 .94-.2 1.82-.54 2.64l1.51 1.51C20.63 14.91 21 13.5 21 12c0-4.28-2.99-7.86-7-8.77v2.06c2.89.86 5 3.54 5 6.71zM4.27 3L3 4.27 7.73 9H3v6h4l5 5v-6.73l4.25 4.25c-.67.52-1.42.93-2.25 1.18v2.06c1.38-.31 2.63-.95 3.69-1.81L19.73 21 21 19.73l-9-9L4.27 3zM12 4L9.91 6.09 12 8.18V4z"/></svg>';
        html += '</div>';
        html += '<span style="flex:1;">禁言管理</span>';
        html += '<span style="color:#FF6B6B;font-size:12px;margin-right:8px;">' + mutedCount + '人被禁言</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 聊天背景设置
        html += '<div class="setting-item" id="group-chat-background" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<div style="width:32px;height:32px;background:linear-gradient(135deg,#A8C8EC,#D6E4FF);border-radius:8px;display:flex;align-items:center;justify-content:center;margin-right:12px;">';
        html += '<svg width="16" height="16" viewBox="0 0 24 24" fill="white"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z"/></svg>';
        html += '</div>';
        html += '<span style="flex:1;">聊天背景</span>';
        html += '<span style="color:#A8C8EC;font-size:12px;margin-right:8px;">' + (group.chatBackground ? '已设置' : '默认') + '</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 【群聊提示词管理】
        var promptCount = (group.prompts || []).length;
        html += '<div class="setting-item" id="group-prompts-setting" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<div style="width:32px;height:32px;background:linear-gradient(135deg,#FFE8F0,#FFD6E8);border-radius:8px;display:flex;align-items:center;justify-content:center;margin-right:12px;">';
        html += '<svg width="16" height="16" viewBox="0 0 24 24" fill="#FF6B8A"><path d="M14 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>';
        html += '</div>';
        html += '<span style="flex:1;">群聊提示词</span>';
        html += '<span style="color:#FF6B8A;font-size:12px;margin-right:8px;">' + promptCount + '个提示词</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 故事记录（封存管理）
        var archiveCount = (group.storyArchives || []).length;
        html += '<div class="setting-item" id="group-story-archive" style="display:flex;align-items:center;padding:15px 20px;border-bottom:1px solid #f0f0f0;cursor:pointer;">';
        html += '<div style="width:32px;height:32px;background:linear-gradient(135deg,#E8F2FF,#D6E4FF);border-radius:8px;display:flex;align-items:center;justify-content:center;margin-right:12px;">';
        html += '<svg width="16" height="16" viewBox="0 0 24 24" fill="#4A6FA5"><path d="M20 6h-8l-2-2H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2zm0 12H4V6h5.17l2 2H20v10z"/></svg>';
        html += '</div>';
        html += '<span style="flex:1;">故事记录</span>';
        html += '<span style="color:#4A6FA5;font-size:12px;margin-right:8px;">' + archiveCount + '个存档</span>';
        html += '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ccc" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>';
        html += '</div>';
        
        // 清空聊天记录
        html += '<div class="setting-item" id="clear-group-history" style="display:flex;align-items:center;padding:15px 20px;cursor:pointer;">';
        html += '<span style="flex:1;color:#FF3B30;">清空聊天记录</span>';
        html += '</div>';
        
        html += '</div>';
        
        // 退出群聊
        html += '<div style="margin-top:20px;background:white;border-radius:16px;overflow:hidden;">';
        html += '<div class="setting-item" id="quit-group" style="display:flex;align-items:center;justify-content:center;padding:15px 20px;cursor:pointer;">';
        html += '<span style="color:#FF3B30;">解散群聊</span>';
        html += '</div>';
        html += '</div>';
        
        html += '</div>';
        
        var settingsPage = this.openDetailPage(html, { title: '群聊设置' });
        
        // 编辑群名称
        var editNameBtn = settingsPage.querySelector('#edit-group-name');
        if (editNameBtn) {
            editNameBtn.onclick = function() {
                var newName = prompt('输入新的群名称：', group.name);
                if (newName && newName.trim()) {
                    group.name = newName.trim();
                    self.saveGroupChat(group);
                    settingsPage.querySelector('.app-back-btn').click();
                }
            };
        }
        
        // 群公告
        var announcementBtn = settingsPage.querySelector('#group-announcement-setting');
        if (announcementBtn) {
            announcementBtn.onclick = function() {
                self.openGroupAnnouncement(groupId);
            };
        }
        
        // 群成员
        var membersBtn = settingsPage.querySelector('#group-members-setting');
        if (membersBtn) {
            membersBtn.onclick = function() {
                self.openGroupMembers(groupId);
            };
        }
        
        // 我的群昵称
        var nicknameBtn = settingsPage.querySelector('#my-group-nickname');
        if (nicknameBtn) {
            nicknameBtn.onclick = function() {
                var currentNickname = group.userNickname || PhoneCore.user.name || '我';
                var newNickname = prompt('设置你在本群的昵称：', currentNickname);
                if (newNickname !== null && newNickname.trim()) {
                    group.userNickname = newNickname.trim();
                    self.saveGroupChat(group);
                    // 更新显示
                    var nicknameSpan = nicknameBtn.querySelector('span:nth-child(2)');
                    if (nicknameSpan) {
                        nicknameSpan.textContent = newNickname.trim();
                    }
                    PhoneCore.notifications.send({
                        type: 'success',
                        title: '群昵称已更新',
                        size: 'mini'
                    });
                }
            };
        }
        
        // 群管理员设置
        var adminsBtn = settingsPage.querySelector('#group-admins-setting');
        if (adminsBtn) {
            adminsBtn.onclick = function() {
                self.openGroupAdminsManager(groupId);
            };
        }
        
        // 禁言管理
        var muteBtn = settingsPage.querySelector('#group-mute-setting');
        if (muteBtn) {
            muteBtn.onclick = function() {
                self.openGroupMuteManager(groupId);
            };
        }
        
        // 聊天背景设置
        var bgBtn = settingsPage.querySelector('#group-chat-background');
        if (bgBtn) {
            bgBtn.onclick = function() {
                self.openChatBackgroundSettings(groupId, 'group');
            };
        }
        
        // 【群聊提示词管理】
        var promptsBtn = settingsPage.querySelector('#group-prompts-setting');
        if (promptsBtn) {
            promptsBtn.onclick = function() {
                self.openGroupPromptsManager(groupId);
            };
        }
        
        // 故事记录（封存管理）
        var storyArchiveBtn = settingsPage.querySelector('#group-story-archive');
        if (storyArchiveBtn) {
            storyArchiveBtn.onclick = function() {
                self.openGroupStoryArchive(groupId);
            };
        }
        
        // 清空聊天记录
        var clearBtn = settingsPage.querySelector('#clear-group-history');
        if (clearBtn) {
            clearBtn.onclick = function() {
                if (confirm('确定要清空所有聊天记录吗？')) {
                    group.chatHistory = [];
                    self.saveGroupChat(group);
                    PhoneCore.notifications.send({
                        type: 'success',
                        title: '聊天记录已清空',
                        size: 'mini'
                    });
                }
            };
        }
        
        // 解散群聊
        var quitBtn = settingsPage.querySelector('#quit-group');
        if (quitBtn) {
            quitBtn.onclick = function() {
                if (confirm('确定要解散该群聊吗？此操作不可恢复。')) {
                    delete self.groupChats[groupId];
                    PhoneCore.db.delete('chat_messages', groupId);
                    
                    // 关闭所有详情页
                    while (self.pageStack && self.pageStack.length > 0) {
                        var p = self.pageStack.pop();
                        if (p) p.remove();
                    }
                    
                    self.refreshChatList();
                    
                    PhoneCore.notifications.send({
                        type: 'success',
                        title: '群聊已解散',
                        size: 'mini'
                    });
                }
            };
        }
    };

    // ============ 群管理员管理 ============
    
    // 打开群管理员管理页面
    ChatApp.prototype.openGroupAdminsManager = function(groupId) {
        var self = this;
        var group = this.getGroupChat(groupId);
        if (!group) return;
        
        // 确保数据结构存在
        if (!group.admins) group.admins = [];
        
        var html = '<div style="padding:20px;">';
        
        // 标题
        html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;">';
        html += '<div style="font-size:18px;font-weight:600;color:#333;">群管理员</div>';
        html += '</div>';
        
        // 说明
        html += '<div style="background:#FFF9E6;border-radius:12px;padding:12px;margin-bottom:20px;font-size:12px;color:#B8860B;line-height:1.6;">';
        html += '• 管理员可以禁言其他成员<br>';
        html += '• 管理员可以修改群名称和公告<br>';
        html += '• AI管理员在群聊中会有管理权限';
        html += '</div>';
        
        // 当前管理员列表
        html += '<div style="font-size:14px;font-weight:500;color:#666;margin-bottom:12px;">当前管理员</div>';
        html += '<div id="admin-list" style="background:white;border-radius:12px;overflow:hidden;margin-bottom:20px;">';
        
        if (group.admins.length === 0) {
            html += '<div style="padding:30px;text-align:center;color:#999;">暂无管理员</div>';
        } else {
            group.admins.forEach(function(adminId) {
                var ai = PhoneCore.getAI(adminId);
                if (!ai) return;
                html += '<div class="admin-item" data-ai-id="' + adminId + '" style="display:flex;align-items:center;padding:12px 15px;border-bottom:1px solid #f0f0f0;">';
                html += '<div style="width:40px;height:40px;border-radius:50%;background:' + self.getAvatarColor(ai.id) + ';margin-right:12px;overflow:hidden;display:flex;align-items:center;justify-content:center;color:white;font-size:16px;">';
                if (ai.avatar) {
                    html += '<img src="' + ai.avatar + '" style="width:100%;height:100%;object-fit:cover;">';
                } else {
                    html += ai.name.charAt(0);
                }
                html += '</div>';
                html += '<div style="flex:1;">';
                html += '<div style="font-weight:500;color:#333;">' + ai.name + '</div>';
                html += '<div style="font-size:11px;color:#FFA500;display:flex;align-items:center;gap:4px;margin-top:2px;"><svg width="10" height="10" viewBox="0 0 24 24" fill="#FFA500"><path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z"/></svg>管理员</div>';
                html += '</div>';
                html += '<button class="remove-admin-btn" data-ai-id="' + adminId + '" style="padding:6px 12px;background:#FF6B6B;color:white;border:none;border-radius:6px;font-size:12px;cursor:pointer;">移除</button>';
                html += '</div>';
            });
        }
        html += '</div>';
        
        // 添加管理员
        html += '<div style="font-size:14px;font-weight:500;color:#666;margin-bottom:12px;">添加管理员</div>';
        html += '<div style="background:white;border-radius:12px;overflow:hidden;">';
        
        var nonAdminMembers = group.members.filter(function(id) { return group.admins.indexOf(id) === -1; });
        if (nonAdminMembers.length === 0) {
            html += '<div style="padding:30px;text-align:center;color:#999;">所有成员都已是管理员</div>';
        } else {
            nonAdminMembers.forEach(function(memberId) {
                var ai = PhoneCore.getAI(memberId);
                if (!ai) return;
                html += '<div class="member-item" data-ai-id="' + memberId + '" style="display:flex;align-items:center;padding:12px 15px;border-bottom:1px solid #f0f0f0;cursor:pointer;transition:background 0.2s;">';
                html += '<div style="width:40px;height:40px;border-radius:50%;background:' + self.getAvatarColor(ai.id) + ';margin-right:12px;overflow:hidden;display:flex;align-items:center;justify-content:center;color:white;font-size:16px;">';
                if (ai.avatar) {
                    html += '<img src="' + ai.avatar + '" style="width:100%;height:100%;object-fit:cover;">';
                } else {
                    html += ai.name.charAt(0);
                }
                html += '</div>';
                html += '<div style="flex:1;">';
                html += '<div style="font-weight:500;color:#333;">' + ai.name + '</div>';
                html += '<div style="font-size:11px;color:#999;margin-top:2px;">' + (ai.type === 'main' ? '主角色' : ai.type === 'supporting' ? '配角' : 'NPC') + '</div>';
                html += '</div>';
                html += '<button class="add-admin-btn" data-ai-id="' + memberId + '" style="padding:6px 12px;background:#FFA500;color:white;border:none;border-radius:6px;font-size:12px;cursor:pointer;">设为管理员</button>';
                html += '</div>';
            });
        }
        html += '</div>';
        
        html += '</div>';
        
        var page = this.openDetailPage(html, { title: '群管理员', backColor: '#FFA500' });
        
        // 绑定事件
        page.querySelectorAll('.add-admin-btn').forEach(function(btn) {
            btn.onclick = function(e) {
                e.stopPropagation();
                var aiId = btn.getAttribute('data-ai-id');
                if (!group.admins) group.admins = [];
                if (group.admins.indexOf(aiId) === -1) {
                    group.admins.push(aiId);
                    self.saveGroupChat(group);
                    self.showToast('已设为管理员');
                    page.querySelector('.app-back-btn').click();
                    setTimeout(function() { self.openGroupAdminsManager(groupId); }, 350);
                }
            };
        });
        
        page.querySelectorAll('.remove-admin-btn').forEach(function(btn) {
            btn.onclick = function(e) {
                e.stopPropagation();
                var aiId = btn.getAttribute('data-ai-id');
                var idx = group.admins.indexOf(aiId);
                if (idx !== -1) {
                    group.admins.splice(idx, 1);
                    self.saveGroupChat(group);
                    self.showToast('已移除管理员');
                    page.querySelector('.app-back-btn').click();
                    setTimeout(function() { self.openGroupAdminsManager(groupId); }, 350);
                }
            };
        });
    };
    
    // ============ 禁言管理 ============
    
    // 打开禁言管理页面
    ChatApp.prototype.openGroupMuteManager = function(groupId) {
        var self = this;
        var group = this.getGroupChat(groupId);
        if (!group) return;
        
        // 确保数据结构存在
        if (!group.mutedMembers) group.mutedMembers = {};
        
        var html = '<div style="padding:20px;">';
        
        // 标题
        html += '<div style="font-size:18px;font-weight:600;color:#333;margin-bottom:20px;">禁言管理</div>';
        
        // 说明
        html += '<div style="background:#FFEBEE;border-radius:12px;padding:12px;margin-bottom:20px;font-size:12px;color:#C62828;line-height:1.6;">';
        html += '• 被禁言的AI将不会在群聊中回复消息<br>';
        html += '• 可设置禁言时长或永久禁言<br>';
        html += '• 管理员不受禁言影响';
        html += '</div>';
        
        // 当前被禁言列表
        var mutedIds = Object.keys(group.mutedMembers);
        html += '<div style="font-size:14px;font-weight:500;color:#666;margin-bottom:12px;">已禁言成员 (' + mutedIds.length + ')</div>';
        html += '<div id="muted-list" style="background:white;border-radius:12px;overflow:hidden;margin-bottom:20px;">';
        
        if (mutedIds.length === 0) {
            html += '<div style="padding:30px;text-align:center;color:#999;">暂无被禁言成员</div>';
        } else {
            mutedIds.forEach(function(mutedId) {
                var ai = PhoneCore.getAI(mutedId);
                if (!ai) return;
                var muteInfo = group.mutedMembers[mutedId];
                var muteEndTime = muteInfo.endTime;
                var isPermanent = muteInfo.permanent || !muteEndTime;
                var muteStatus = isPermanent ? '永久禁言' : '至 ' + new Date(muteEndTime).toLocaleString();
                
                html += '<div class="muted-item" data-ai-id="' + mutedId + '" style="display:flex;align-items:center;padding:12px 15px;border-bottom:1px solid #f0f0f0;">';
                html += '<div style="width:40px;height:40px;border-radius:50%;background:' + self.getAvatarColor(ai.id) + ';margin-right:12px;overflow:hidden;display:flex;align-items:center;justify-content:center;color:white;font-size:16px;filter:grayscale(50%);">';
                if (ai.avatar) {
                    html += '<img src="' + ai.avatar + '" style="width:100%;height:100%;object-fit:cover;">';
                } else {
                    html += ai.name.charAt(0);
                }
                html += '</div>';
                html += '<div style="flex:1;">';
                html += '<div style="font-weight:500;color:#333;">' + ai.name + '</div>';
                html += '<div style="font-size:11px;color:#FF6B6B;display:flex;align-items:center;gap:4px;margin-top:2px;"><svg width="10" height="10" viewBox="0 0 24 24" fill="#FF6B6B"><path d="M16.5 12c0-1.77-1.02-3.29-2.5-4.03v2.21l2.45 2.45c.03-.2.05-.41.05-.63z"/></svg>' + muteStatus + '</div>';
                html += '</div>';
                html += '<button class="unmute-btn" data-ai-id="' + mutedId + '" style="padding:6px 12px;background:#4ade80;color:white;border:none;border-radius:6px;font-size:12px;cursor:pointer;">解除禁言</button>';
                html += '</div>';
            });
        }
        html += '</div>';
        
        // 禁言成员
        html += '<div style="font-size:14px;font-weight:500;color:#666;margin-bottom:12px;">禁言成员</div>';
        html += '<div style="background:white;border-radius:12px;overflow:hidden;">';
        
        var unmutedMembers = group.members.filter(function(id) { return !group.mutedMembers[id]; });
        if (unmutedMembers.length === 0) {
            html += '<div style="padding:30px;text-align:center;color:#999;">所有成员都已被禁言</div>';
        } else {
            unmutedMembers.forEach(function(memberId) {
                var ai = PhoneCore.getAI(memberId);
                if (!ai) return;
                var isAdmin = group.admins && group.admins.indexOf(memberId) !== -1;
                html += '<div class="member-item" data-ai-id="' + memberId + '" style="display:flex;align-items:center;padding:12px 15px;border-bottom:1px solid #f0f0f0;">';
                html += '<div style="width:40px;height:40px;border-radius:50%;background:' + self.getAvatarColor(ai.id) + ';margin-right:12px;overflow:hidden;display:flex;align-items:center;justify-content:center;color:white;font-size:16px;">';
                if (ai.avatar) {
                    html += '<img src="' + ai.avatar + '" style="width:100%;height:100%;object-fit:cover;">';
                } else {
                    html += ai.name.charAt(0);
                }
                html += '</div>';
                html += '<div style="flex:1;">';
                html += '<div style="font-weight:500;color:#333;">' + ai.name + (isAdmin ? ' <span style="font-size:10px;color:#FFA500;">管理员</span>' : '') + '</div>';
                html += '<div style="font-size:11px;color:#999;margin-top:2px;">' + (ai.type === 'main' ? '主角色' : ai.type === 'supporting' ? '配角' : 'NPC') + '</div>';
                html += '</div>';
                if (!isAdmin) {
                    html += '<button class="mute-btn" data-ai-id="' + memberId + '" style="padding:6px 12px;background:#FF6B6B;color:white;border:none;border-radius:6px;font-size:12px;cursor:pointer;">禁言</button>';
                } else {
                    html += '<span style="font-size:11px;color:#999;">管理员免禁言</span>';
                }
                html += '</div>';
            });
        }
        html += '</div>';
        
        html += '</div>';
        
        var page = this.openDetailPage(html, { title: '禁言管理', backColor: '#FF6B6B' });
        
        // 绑定禁言按钮
        page.querySelectorAll('.mute-btn').forEach(function(btn) {
            btn.onclick = function(e) {
                e.stopPropagation();
                var aiId = btn.getAttribute('data-ai-id');
                self.showMuteOptionsDialog(groupId, aiId, page);
            };
        });
        
        // 绑定解除禁言按钮
        page.querySelectorAll('.unmute-btn').forEach(function(btn) {
            btn.onclick = function(e) {
                e.stopPropagation();
                var aiId = btn.getAttribute('data-ai-id');
                delete group.mutedMembers[aiId];
                self.saveGroupChat(group);
                self.showToast('已解除禁言');
                page.querySelector('.app-back-btn').click();
                setTimeout(function() { self.openGroupMuteManager(groupId); }, 350);
            };
        });
    };
    
    // 显示禁言选项对话框
    ChatApp.prototype.showMuteOptionsDialog = function(groupId, aiId, parentPage) {
        var self = this;
        var group = this.getGroupChat(groupId);
        var ai = PhoneCore.getAI(aiId);
        if (!group || !ai) return;
        
        var container = this.appWindow || document.body;
        
        var modalHtml = '<div id="mute-dialog" style="position:absolute;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:9999;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.2s ease;">';
        modalHtml += '<div style="width:85%;max-width:300px;background:white;border-radius:16px;overflow:hidden;animation:slideUp 0.3s ease;">';
        modalHtml += '<div style="padding:20px;text-align:center;">';
        modalHtml += '<div style="font-size:16px;font-weight:600;color:#333;margin-bottom:8px;">禁言 ' + ai.name + '</div>';
        modalHtml += '<div style="font-size:13px;color:#666;margin-bottom:20px;">选择禁言时长</div>';
        modalHtml += '</div>';
        
        modalHtml += '<div style="border-top:1px solid #f0f0f0;">';
        modalHtml += '<div class="mute-option" data-duration="10" style="padding:14px;text-align:center;border-bottom:1px solid #f0f0f0;cursor:pointer;transition:background 0.2s;">10分钟</div>';
        modalHtml += '<div class="mute-option" data-duration="30" style="padding:14px;text-align:center;border-bottom:1px solid #f0f0f0;cursor:pointer;transition:background 0.2s;">30分钟</div>';
        modalHtml += '<div class="mute-option" data-duration="60" style="padding:14px;text-align:center;border-bottom:1px solid #f0f0f0;cursor:pointer;transition:background 0.2s;">1小时</div>';
        modalHtml += '<div class="mute-option" data-duration="1440" style="padding:14px;text-align:center;border-bottom:1px solid #f0f0f0;cursor:pointer;transition:background 0.2s;">1天</div>';
        modalHtml += '<div class="mute-option" data-duration="-1" style="padding:14px;text-align:center;border-bottom:1px solid #f0f0f0;cursor:pointer;transition:background 0.2s;color:#FF6B6B;">永久禁言</div>';
        modalHtml += '<div class="mute-cancel" style="padding:14px;text-align:center;cursor:pointer;color:#666;">取消</div>';
        modalHtml += '</div>';
        
        modalHtml += '</div>';
        modalHtml += '</div>';
        
        var modal = document.createElement('div');
        modal.innerHTML = modalHtml;
        container.appendChild(modal.firstChild);
        
        var modalEl = container.querySelector('#mute-dialog');
        
        // 绑定选项
        modalEl.querySelectorAll('.mute-option').forEach(function(opt) {
            opt.onmouseenter = function() { opt.style.background = '#f5f5f5'; };
            opt.onmouseleave = function() { opt.style.background = ''; };
            opt.onclick = function() {
                var duration = parseInt(opt.getAttribute('data-duration'));
                if (!group.mutedMembers) group.mutedMembers = {};
                
                if (duration === -1) {
                    group.mutedMembers[aiId] = { permanent: true, startTime: Date.now() };
                } else {
                    group.mutedMembers[aiId] = { 
                        permanent: false, 
                        startTime: Date.now(),
                        endTime: Date.now() + duration * 60 * 1000
                    };
                }
                
                self.saveGroupChat(group);
                modalEl.remove();
                self.showToast(ai.name + ' 已被禁言');
                parentPage.querySelector('.app-back-btn').click();
                setTimeout(function() { self.openGroupMuteManager(groupId); }, 350);
            };
        });
        
        // 取消按钮
        modalEl.querySelector('.mute-cancel').onclick = function() {
            modalEl.style.animation = 'fadeOut 0.2s ease';
            setTimeout(function() { modalEl.remove(); }, 200);
        };
        
        // 点击背景关闭
        modalEl.onclick = function(e) {
            if (e.target === modalEl) {
                modalEl.style.animation = 'fadeOut 0.2s ease';
                setTimeout(function() { modalEl.remove(); }, 200);
            }
        };
    };
    
    // 检查成员是否被禁言
    ChatApp.prototype.isMemberMuted = function(group, memberId) {
        if (!group || !group.mutedMembers || !group.mutedMembers[memberId]) {
            return false;
        }
        
        // 管理员免禁言
        if (group.admins && group.admins.indexOf(memberId) !== -1) {
            return false;
        }
        
        var muteInfo = group.mutedMembers[memberId];
        
        if (muteInfo.permanent) {
            return true;
        }
        
        if (muteInfo.endTime && Date.now() < muteInfo.endTime) {
            return true;
        }
        
        // 禁言已过期，自动清除
        if (muteInfo.endTime && Date.now() >= muteInfo.endTime) {
            delete group.mutedMembers[memberId];
            this.saveGroupChat(group);
            return false;
        }
        
        return false;
    };
    
