        html += '</div>';
        html += '</div>';
        
        // 清除背景
        if (currentBg) {
            html += '<button id="clear-bg-btn" style="width:100%;padding:14px;background:#FF6B6B;color:white;border:none;border-radius:10px;font-size:15px;cursor:pointer;margin-top:10px;">清除背景</button>';
        }
        
        html += '</div>';
