            html += '<div style="font-size:12px;color:#888;margin-top:2px;">';
            if (pendingRequests.length === 1) {
                html += pendingRequests[0].aiName + '请求恢复聊天';
            } else {
                html += pendingRequests[0].aiName + '等' + pendingRequests.length + '人请求恢复聊天';
            }
            html += '</div>';
            html += '</div>';
            html += '</div>';
