            { svg: '<svg width="32" height="32" viewBox="0 0 24 24" fill="#0EA5E9"><path d="M4 19h16l-2-9H6l-2 9z"/><path d="M8 10V7l4-4 4 4v3" fill="#0EA5E9"/><circle cx="12" cy="14" r="2" fill="white"/></svg>', text: '旅行中', color: '#0EA5E9' },
            { svg: '<svg width="32" height="32" viewBox="0 0 24 24" fill="#F59E0B"><path d="M5 8h14l-1 10H6L5 8z" stroke="#F59E0B" stroke-width="1.5"/><rect x="3" y="8" width="18" height="4" rx="1" fill="#F59E0B"/><path d="M8 4h8v4H8z" fill="#78350F"/></svg>', text: '吃饭中', color: '#F59E0B' },
            { svg: '<svg width="32" height="32" viewBox="0 0 24 24" fill="#6366F1"><path d="M12 3c-4.97 0-9 4.03-9 9s4.03 9 9 9 9-4.03 9-9c0-.46-.04-.92-.1-1.36-.98 1.37-2.58 2.26-4.4 2.26-3.03 0-5.5-2.47-5.5-5.5 0-1.82.89-3.42 2.26-4.4-.44-.06-.9-.1-1.36-.1z"/></svg>', text: '晚安', color: '#6366F1' }
